#import "IndiaSubscriptionsReactNative.h"

#import <React/RCTBridgeModule.h>
#import <React/RCTInvalidating.h>

// The Swift half of the pod (IndiaSubscriptionsBridge). The header is generated by the Swift compiler: with static
// libraries it is imported by its plain name, with frameworks through the module.
#if __has_include("IndiaSubscriptionsReactNative-Swift.h")
#import "IndiaSubscriptionsReactNative-Swift.h"
#else
#import <IndiaSubscriptionsReactNative/IndiaSubscriptionsReactNative-Swift.h>
#endif

/**
 * The Turbo Native Module: converts nothing and decides nothing. Every call goes to `IndiaSubscriptionsBridge`, which
 * drives the Swift package, and every result comes back as a plain dictionary for JavaScript.
 */
@interface IndiaSubscriptionsReactNative () <RCTInvalidating>
@end

@implementation IndiaSubscriptionsReactNative {
  IndiaSubscriptionsBridge *_bridge;
}

- (instancetype)init
{
  if (self = [super init]) {
    _bridge = [IndiaSubscriptionsBridge new];
    __weak __typeof(self) weakSelf = self;
    // Events come from the Swift client on any thread; React Native's event emitter is thread-safe.
    [_bridge setEventSink:^(NSDictionary *event) {
      [weakSelf emitOnPurchaseEvent:event];
    }];
  }
  return self;
}

+ (NSString *)moduleName
{
  return @"IndiaSubscriptionsReactNative";
}

// A JavaScript reload ends this instance: stop forwarding. The client lives on in the Swift runtime, and the next
// `configure` call replaces it.
- (void)invalidate
{
  [_bridge detach];
}

- (void)configure:(NSDictionary *)options resolve:(RCTPromiseResolveBlock)resolve reject:(RCTPromiseRejectBlock)reject
{
  [_bridge configure:options resolve:resolve reject:reject];
}

- (void)setAuthorization:(NSString *)value resolve:(RCTPromiseResolveBlock)resolve reject:(RCTPromiseRejectBlock)reject
{
  [_bridge setAuthorization:value resolve:resolve reject:reject];
}

- (void)start:(RCTPromiseResolveBlock)resolve reject:(RCTPromiseRejectBlock)reject
{
  [_bridge start:resolve reject:reject];
}

- (void)stop:(RCTPromiseResolveBlock)resolve reject:(RCTPromiseRejectBlock)reject
{
  [_bridge stop:resolve reject:reject];
}

- (void)purchase:(NSString *)product
         options:(NSDictionary *)options
         resolve:(RCTPromiseResolveBlock)resolve
          reject:(RCTPromiseRejectBlock)reject
{
  [_bridge purchase:product options:options resolve:resolve reject:reject];
}

- (void)processPending:(RCTPromiseResolveBlock)resolve reject:(RCTPromiseRejectBlock)reject
{
  [_bridge processPending:resolve reject:reject];
}

- (void)retryRejected:(RCTPromiseResolveBlock)resolve reject:(RCTPromiseRejectBlock)reject
{
  [_bridge retryRejected:resolve reject:reject];
}

- (void)restorePurchases:(NSString *)customerRef resolve:(RCTPromiseResolveBlock)resolve reject:(RCTPromiseRejectBlock)reject
{
  [_bridge restorePurchases:customerRef resolve:resolve reject:reject];
}

- (void)entitlements:(NSString *)customerRef resolve:(RCTPromiseResolveBlock)resolve reject:(RCTPromiseRejectBlock)reject
{
  [_bridge entitlements:customerRef resolve:resolve reject:reject];
}

- (void)showManageSubscriptions:(RCTPromiseResolveBlock)resolve reject:(RCTPromiseRejectBlock)reject
{
  [_bridge showManageSubscriptions:resolve reject:reject];
}

- (void)requestRefund:(NSString *)transactionId resolve:(RCTPromiseResolveBlock)resolve reject:(RCTPromiseRejectBlock)reject
{
  [_bridge requestRefund:transactionId resolve:resolve reject:reject];
}

- (void)subscriptionManagementUrl:(NSString *)productId
                          resolve:(RCTPromiseResolveBlock)resolve
                           reject:(RCTPromiseRejectBlock)reject
{
  [_bridge subscriptionManagementUrl:productId resolve:resolve reject:reject];
}

- (void)handleReturnLink:(NSString *)url resolve:(RCTPromiseResolveBlock)resolve reject:(RCTPromiseRejectBlock)reject
{
  [_bridge handleReturnLink:url resolve:resolve reject:reject];
}

- (std::shared_ptr<facebook::react::TurboModule>)getTurboModule:
    (const facebook::react::ObjCTurboModule::InitParams &)params
{
  return std::make_shared<facebook::react::NativeIndiaSubscriptionsReactNativeSpecJSI>(params);
}

@end
